"""Pure-Python git metadata detection.

This module reads git's internal filesystem data structures directly (``.git/HEAD``,
``.git/refs``, ``.git/packed-refs``, ``.git/config``) instead of shelling out to the
``git`` executable. This keeps source code location detection dependency-free and
avoids the overhead and failure modes of spawning subprocesses.
"""
from __future__ import annotations

import configparser
import logging
from pathlib import Path

log = logging.getLogger(__name__)

_GITDIR_PREFIX = "gitdir:"
_REF_PREFIX = "ref:"
_HEADS_PREFIX = "refs/heads/"
_TAGS_PREFIX = "refs/tags/"


def _find_git_dir(path: str) -> Path | None:
    """Traverse upward from *path* to locate the git directory.

    Returns the ``.git`` directory as a ``Path`` when it is a real directory. When
    ``.git`` is a file (a linked worktree) containing a ``gitdir: <pointer>`` line, the
    pointer is resolved (absolute as-is, relative to the ``.git`` file's parent) and
    returned. Returns ``None`` when no ``.git`` entry exists anywhere in the hierarchy.
    """
    start = Path(path)
    for directory in (start, *start.parents):
        git_path = directory / ".git"
        if git_path.is_dir():
            return git_path
        if git_path.is_file():
            try:
                content = git_path.read_text().strip()
            except OSError:
                return None
            if content.startswith(_GITDIR_PREFIX):
                pointer = content[len(_GITDIR_PREFIX) :].strip()
                pointer_path = Path(pointer)
                if not pointer_path.is_absolute():
                    pointer_path = (git_path.parent / pointer_path).resolve()
                return pointer_path
            return None
    return None


def _read_head_content(git_dir: Path) -> str | None:
    """Read ``git_dir/HEAD`` with trailing whitespace stripped, or ``None`` if absent."""
    head = git_dir / "HEAD"
    if not head.exists():
        return None
    try:
        return head.read_text().rstrip()
    except OSError:
        return None


def _resolve_ref(git_dir: Path, ref: str) -> str | None:
    """Resolve a ref (e.g. ``refs/heads/main``) to a commit SHA.

    Checks the loose file at ``git_dir/ref`` first, then searches ``git_dir/packed-refs``.
    Returns ``None`` when the ref is found in neither location.
    """
    loose = git_dir / ref
    if loose.is_file():
        try:
            return loose.read_text().strip()
        except OSError:
            return None

    packed = git_dir / "packed-refs"
    if packed.is_file():
        try:
            lines = packed.read_text().splitlines()
        except OSError:
            return None
        for raw in lines:
            line = raw.strip()
            if not line or line.startswith(("#", "^")):
                continue
            sha, _, name = line.partition(" ")
            if name.strip() == ref:
                return sha.strip()
    return None


def _read_head_sha(git_dir: Path) -> str | None:
    """Return the commit SHA that HEAD points to.

    Handles detached HEAD (a raw SHA) and symbolic refs (``ref: refs/heads/<branch>``,
    resolved via :func:`_resolve_ref`). Returns ``None`` when HEAD does not exist.
    """
    content = _read_head_content(git_dir)
    if content is None:
        return None
    if content.startswith(_REF_PREFIX):
        ref = content[len(_REF_PREFIX) :].strip()
        return _resolve_ref(git_dir, ref)
    return content


def _find_tag_in_packed_refs(git_dir: Path, sha: str) -> str | None:
    """Search ``git_dir/packed-refs`` for a tag pointing at *sha*.

    Lightweight tags carry the SHA directly on the ``<sha> refs/tags/<name>`` line.
    Annotated tags carry the commit SHA on the ``^<sha>`` dereference line that
    immediately follows the tag entry. Returns the tag name (the part after
    ``refs/tags/``), or ``None`` when ``packed-refs`` is absent, the SHA matches no tag,
    or the matching ref is not under ``refs/tags/``.
    """
    packed = git_dir / "packed-refs"
    if not packed.is_file():
        return None
    try:
        lines = packed.read_text().splitlines()
    except OSError:
        return None

    prev_tag: str | None = None
    for raw in lines:
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        if line.startswith("^"):
            # Dereference line: the peeled commit SHA of the preceding tag object.
            if prev_tag is not None and line[1:].strip() == sha:
                return prev_tag
            continue
        line_sha, _, name = line.partition(" ")
        name = name.strip()
        if name.startswith(_TAGS_PREFIX):
            tag_name = name[len(_TAGS_PREFIX) :]
            if line_sha.strip() == sha:
                return tag_name
            prev_tag = tag_name
        else:
            prev_tag = None
    return None


def get_git_version(git_dir: Path) -> str | None:
    """Return the current commit SHA, or ``None`` when HEAD is missing."""
    return _read_head_sha(git_dir)


def get_git_branch(git_dir: Path) -> str | None:
    """Return the current branch name (``refs/heads/`` prefix stripped).

    Returns ``None`` when HEAD is detached (a raw SHA) or does not exist.
    """
    content = _read_head_content(git_dir)
    if content is None:
        return None
    if not content.startswith(_REF_PREFIX):
        return None
    ref = content[len(_REF_PREFIX) :].strip()
    if ref.startswith(_HEADS_PREFIX):
        return ref[len(_HEADS_PREFIX) :]
    return None


def get_git_tag(git_dir: Path) -> str | None:
    """Return the tag name pointing at the current commit.

    Loose tag files under ``git_dir/refs/tags`` are searched recursively first, falling
    back to :func:`_find_tag_in_packed_refs`. Returns the tag name relative to
    ``refs/tags/``, or ``None`` when no matching tag is found or HEAD is missing.
    """
    sha = _read_head_sha(git_dir)
    if sha is None:
        return None

    tags_dir = git_dir / "refs" / "tags"
    if tags_dir.is_dir():
        for tag_file in sorted(tags_dir.rglob("*")):
            if not tag_file.is_file():
                continue
            try:
                content = tag_file.read_text().strip()
            except OSError:
                continue
            if content == sha:
                return tag_file.relative_to(tags_dir).as_posix()

    return _find_tag_in_packed_refs(git_dir, sha)


